#: D1. THE FUZZ RUNS AT THE RATE AT WHICH RANKING ACTUALLY HAPPENS.
#:
#: The previous suite ran only at 48 kHz and certified `mcd` "gain-invariant"
#: (5.5e-07) at a rate where NO RANKING IS EVER COMPUTED. M2 makes
#: REFERENCE-NATIVE a within-arm denominator, so every cross-arm ranking happens
#: at REFERENCE-COMMON = 16 kHz - and at 16 kHz the shipped `mcd` scored a pure
#: x2 gain at 25.84, i.e. 10.75% of the mildest damage rung.
#:
#: 16 kHz is PRIMARY. 48 kHz is retained as a secondary record so a rate-specific
#: defect is visible as a difference between them rather than invisible.
RANK_SR = 16000
SECONDARY_SR = 48000

#: D3. The alignment tolerance must be TIGHTER THAN THE ALIGNMENT QUANTUM, or the
#: test cannot fail. The previous tolerance was set EQUAL to one envelope hop, so
#: `delayed_100 -> reported 0` was recorded as `delay_recovered: True`.
ALIGN_TOL_SAMPLES = 8

#: D3. The residual alignment error is judged by what it COSTS the ranking
#: metric, as a fraction of the mildest declared damage rung.
#:
#: TWO SEPARATE QUANTITIES, and conflating them is how a floor gets tuned:
#:
#:  CLEAN-SIGNAL BUDGET - a hard gate. On phase-COHERENT input the aligner must
#:  be essentially exact. Failing this means the aligner is broken.
ALIGN_CLEAN_MAX_FRACTION = 0.02
#:
#:  D2 / D3. PHASE-INCOHERENT RESIDUAL - NOT a gate, a MEASUREMENT. Randomising
#:  phase genuinely smears energy inside each analysis frame, so the envelope
#:  peak moves by a few samples. That is physics, not a defect, and it cannot be
#:  tuned away. It is MEASURED and EXPORTED as the INSTRUMENT FLOOR: the smallest
#:  difference this apparatus can attribute to a decoder rather than to its own
#:  alignment. This is the non-zero, chain-specific floor that `rate_chain_floor`
#:  failed to provide (it returns exactly 0.0 for 15 of 18 arms, because they all
#:  have sr_in == sr_out).
ALIGN_RESIDUAL_MAX_FRACTION = ALIGN_CLEAN_MAX_FRACTION
SEX = {"Speaker_01": "Female", "Speaker_02": "Female", "Speaker_04": "Female",
       "Speaker_05": "Female", "Speaker_07": "Female", "Speaker_03": "Male", "Speaker_06": "Male"}

#: F5. Every state the corpus carries. A ranking metric must satisfy the declared
#: rule in ALL of them.
ALL_STATES = ("Neutral", "Angry", "Happy", "Scared", "Shouting", "Whisper")

#: F2. THE INSTRUMENT FLOOR IS A DISTRIBUTION, NOT ONE DRAW. Frozen here before
