N_FLOOR_DRAWS = 16
FLOOR_QUANTILE = 0.95
FLOOR_DELAYS = (7, 40, 100, 333, 1000)
#: ⚠️ DECLARED AS A MIXTURE. These five delays are pooled into ONE distribution
#: per state. They are NOT the operational delay distribution: Gate 3's measured
#: arm delays are 15-36 ms (240-576 samples at 16 kHz), which falls between the
#: 100 and 333 sample probes. Pooled medians by delay are 0.139 / 0.298 / 0.242 /
#: 0.195 / 0.232 - no monotone trend, so no evident bias - but the construction
