#: The boundary is set by the arms' Nyquist, not by which metric survives - but
#: the fact that it was chosen after seeing both is recorded, and the 2 kHz
#: result is still COMPUTED AND REPORTED for every metric and every state.
GATE_BAND_LIMITS_HZ = (7000.0, 6000.0, 4000.0)


def rng_for(name):
    """m9. Per-metric deterministic RNG - order-independent."""
    return np.random.default_rng(SEED + zlib.crc32(name.encode()))


# ---------------------------------------------------------------- material

def _load(spk, state, idx):
    import glob
    d = os.path.join(SRC, SEX[spk], spk, "English", state)
    g = sorted(glob.glob(os.path.join(d, "%04d_*.wav" % idx)))
    if not g:
        raise FileNotFoundError(f"{spk}/{state}/{idx:04d}")
    x, sr = sf.read(g[0], dtype="float64", always_2d=True)
    return x.mean(axis=1), int(sr), g[0]


def calibration_material():
    """⭐ M7. HELD-OUT material, from the corpus artifact, spanning states.

    The calibration indices sit in [2.0, 3.0) s on NEUTRAL, which the Set S
    predicate ([3.0, 10.0] s) excludes BY CONSTRUCTION - so no floor that
    licenses a ranking is derived from a recording the ranking is computed on.
    """
    if not os.path.isfile(CORPUS):
        raise SystemExit(
            "GATE4_CORPUS.json not found. Run `python gate4_corpus.py` first - "
            "the fuzz must calibrate on the held-out subset that file declares, "
            "never on the evaluation set (M7).")
    doc = json.load(open(CORPUS))
    idx = doc["calibration"]["indices"]
    if not idx:
        raise SystemExit("calibration subset is empty - STOP")
    setS = set(doc["set_S"]["indices"])
    setL = set(doc["set_L"]["indices"])
    assert not (set(idx) & setS), "calibration overlaps Set S"
    assert not (set(idx) & setL), "calibration overlaps Set L"

    # Reference and the unrelated bound: different speaker, different text,
    # and states that include the hard case.
    pairs = []
    # F5. ALL SIX STATES. The calibration subset already holds all six on disk
    # (126 cells = 3 indices x 7 speakers x 6 states, hashed), and the per-state
    # gate flipped 6 of 9 verdicts on only three of them - so Angry, Happy and
    # Scared were never exercised while the document claimed a metric "must pass
    # in ALL of them".
    for state in ALL_STATES:
        ref, sr, pr = _load("Speaker_06", state, idx[0])
        oth, _, po = _load("Speaker_01", state, idx[min(1, len(idx) - 1)])
        # D1. Bring the material to the RANKING RATE through the ONE canonical
        # resampler (B10). The battery must exercise the metric at the rate at
        # which it is actually allowed to rank, not at the source rate.
        ref_r, _ = G4.resample(ref, sr, RANK_SR)
        oth_r, _ = G4.resample(oth, sr, RANK_SR)
        pairs.append({"state": state, "ref": ref_r, "sr": RANK_SR,
                      "source_sr": sr,
                      "ref_native": ref, "other_native": oth,
                      "other": oth_r, "ref_path": os.path.basename(pr),
                      "other_path": os.path.basename(po)})
    return pairs, idx, doc


# ---------------------------------------------------------------- perturbations

def shift(x, k):
    if k == 0:
        return x.copy()
    return np.concatenate([np.zeros(k), x[:-k]])


def add_noise(x, snr_db, rng):
    p = float((x ** 2).mean())
    if p <= 0:
        return x.copy()
    return x + rng.normal(0.0, np.sqrt(p / (10.0 ** (snr_db / 10.0))), size=x.shape)


def band_limit(x, sr, cutoff):
    X = np.fft.rfft(x)
    X[np.fft.rfftfreq(x.size, 1.0 / sr) > cutoff] = 0.0
    return np.fft.irfft(X, n=x.size)


def destroy_phase(x, sr, rng, win_ms=25.0, hop_ms=5.0):
    """⭐ B7's decisive probe: randomise phase PER STFT FRAME, then overlap-add.

    ⛔ THE FIRST VERSION OF THIS PROBE WAS WRONG AND THE FUZZ CAUGHT IT. It
    randomised phase across the WHOLE signal at once, which does not merely
    decohere the waveform - it SMEARS THE SIGNAL ACROSS ITS ENTIRE DURATION and
    destroys the temporal envelope. Measured envelope correlation against the
    reference: 0.075. That probe tested nothing a vocoder does, and it made a
    correct aligner look broken.

    A neural decoder that resynthesises phase PRESERVES the envelope - it places
    the same energy at the same instants - and only the fine phase differs.
    Per-frame randomisation with overlap-add reproduces exactly that.
    """
    import torch
    win = max(16, int(round(win_ms * sr / 1000.0)))
    hop = max(1, int(round(hop_ms * sr / 1000.0)))
    n_fft = 1 << int(np.ceil(np.log2(win)))
    t = torch.from_numpy(x).float()
    w = torch.hann_window(win)
    S = torch.stft(t, n_fft=n_fft, hop_length=hop, win_length=win, window=w,
                   return_complex=True, center=True)
    mag = S.abs()
    ph = torch.from_numpy(rng.uniform(-np.pi, np.pi, size=tuple(mag.shape))).float()
    y = torch.istft(mag * torch.exp(1j * ph), n_fft=n_fft, hop_length=hop,
                    win_length=win, window=w, center=True, length=x.size)
    return y.numpy().astype(np.float64)


# ---------------------------------------------------------------- runner

def call(fn, *a, **k):
    try:
        r = fn(*a, **k)
    except Exception as e:
        return {"value": None, "state": "RAISED",
                "error": f"{type(e).__name__}: {e}"[:200]}
    if isinstance(r, dict):
        v = r.get("value")
        if isinstance(v, dict):
            r = dict(r)
            r["value"] = v.get("jump_ratio", {}).get("median")
        return r
    return {"value": r, "state": "MEASURED"}


def num(rec):
    v = rec.get("value")
    return v if isinstance(v, (int, float)) and np.isfinite(v) else None


def state_gates(sp, ladder_db):
    """D9. The same five gates, evaluated on ONE state's probes.

    A metric that orders damage correctly on Neutral and fails on Whisper cannot
    rank arms on a corpus containing both. Every state must pass.
    """
    ident = num(sp["identical"])
    s1 = num(sp["shift_1"])
    lad = [num(sp[f"noise_{int(d)}dB"]) for d in ladder_db]
    st_id = sp["identical"].get("state")
    g1 = bool((ident is not None and abs(ident) < 1e-9) or st_id == "DEGENERATE")
    if all(l is not None for l in lad):
        inc = all(lad[i + 1] > lad[i] for i in range(len(lad) - 1))
        dec = all(lad[i + 1] < lad[i] for i in range(len(lad) - 1))
        g2, direction = bool(inc or dec), ("increases" if inc else
                                           ("decreases" if dec else "neither"))
    else:
        g2, direction = False, "UNKNOWN"
    if None not in (s1, lad[0]) and direction in ("increases", "decreases"):
        worse = (s1 > lad[0]) if direction == "increases" else (s1 < lad[0])
        g3 = bool(not worse)
    else:
        g3 = False
    tstate = sp["truncated_256"].get("state")
    g4 = bool(tstate in ("LENGTH FAILURE", "UNKNOWN", "RAISED")
              or (num(sp["truncated_256"]) is not None and ident is not None
                  and abs(num(sp["truncated_256"]) - ident) > 1e-9))
    az, st_az = num(sp["all_zero"]), sp["all_zero"].get("state")
    worst = lad[-1] if lad and lad[-1] is not None else None
    if st_az in ("DEGENERATE", "UNKNOWN", "RAISED", "LENGTH FAILURE"):
        g5 = True
    elif None in (az, worst, ident):
        g5 = False
    else:
        g5 = bool(abs(az - ident) > abs(worst - ident))
    # G6. SPECTRAL SUPPORT. A band-limited version of the SAME utterance must
    # stay CLOSER than a DIFFERENT SPEAKER, or the metric is scoring how much
    # band a decoder retained rather than how faithful it was.
    unrel = num(sp.get("different_speaker", {}))
    bands = {k: num(v) for k, v in sp.items() if k.startswith("band_")
             and float(k.split("_")[1]) in GATE_BAND_LIMITS_HZ}
    if unrel is None or not bands or any(v is None for v in bands.values()):
        g6, g6_worst = False, None
    else:
        if direction == "increases":
            g6_worst = max(bands.values())
            g6 = bool(g6_worst < unrel)
        elif direction == "decreases":
            g6_worst = min(bands.values())
            g6 = bool(g6_worst > unrel)
        else:
            g6, g6_worst = False, None
    # G7. GAIN, per state. `gain_x2.0` was collected and read by nothing.
    gv, idv = num(sp.get("gain_x2.0", {})), ident
    if gv is None or idv is None:
        g7 = (sp.get("gain_x2.0", {}).get("state") == "DEGENERATE")
    else:
        scale = abs(lad[0] - idv) if (lad and lad[0] is not None) else None
        g7 = bool(abs(gv - idv) <= 0.01 * scale) if scale else bool(abs(gv - idv) < 1e-9)
    return {"G1": g1, "G2": g2, "G3": g3, "G4": g4, "G5": g5,
            "G6_spectral_support": g6, "G6_worst_band": g6_worst,
            "G6_unrelated": unrel, "G7_gain_invariant": g7,
            "direction": direction, "ladder": lad,
            "all_pass": bool(g1 and g2 and g3 and g4 and g5 and g6 and g7)}
    # G7 was computed per state and EXCLUDED from all_pass - the accounting
    # was off even though no outcome changed (mcd passes G7 in all six
    # states, 6.62e-13 to 7.24e-13). It now counts.


# ---------------------------------------------------------------- alignment fuzz

def fuzz_alignment(ref, sr, other, rng):
    """⭐ B7 + M10. The admissibility gate that decides tier-B for every
    source-referenced number had never been fuzzed at all.

    The decisive probe is PHASE DESTRUCTION AT A KNOWN DELAY: a signal with the
    reference's exact magnitude spectrum, randomised phase, and a delay we
    imposed. A correct aligner recovers the delay. The OLD raw-waveform method is
    run on the same material for comparison, so the repair is demonstrated rather
    than asserted.
    """
    import torch
    import gate3_lib as L3
    out = {"method": "envelope", "threshold": G4.ALIGN_MIN_ENV_CORR, "probes": {}}
    P = out["probes"]

    def old_r(a, b):
        d = L3.estimate_delay(torch.from_numpy(a).float().reshape(1, -1),
                              torch.from_numpy(b).float().reshape(1, -1), sr)
        return d.get("normalised_peak_correlation"), d.get("delay_samples")

    def probe(tag, est, expect_delay=None):
        a = G4.alignment(ref, est, sr)
        r_old, d_old = old_r(ref, est)
        rec = {"envelope_r": a.get("envelope_correlation"),
               "envelope_delay_samples": a.get("delay_samples"),
               "state": a["state"], "expected_delay_samples": expect_delay,
               "OLD_raw_waveform_r": r_old, "OLD_raw_waveform_delay": d_old}
        if expect_delay is not None and a.get("delay_samples") is not None:
            # D3. TOLERANCE IS TIGHTER THAN THE ALIGNMENT QUANTUM. It was
            # previously set EQUAL to one envelope hop, which made the test
            # unable to fail: `delayed_100 -> reported 0` passed.
            resid = abs(a["delay_samples"] - expect_delay)
            rec["residual_samples"] = int(resid)
            rec["delay_recovered"] = bool(resid <= ALIGN_TOL_SAMPLES)
            rec["delay_tolerance_samples"] = ALIGN_TOL_SAMPLES
            rec["alignment_quantum_samples"] = int(round(G4.ENV_HOP_MS * sr / 1000.0))
        P[tag] = rec

    probe("identical", ref, 0)
    # D3. Sub-hop delays are probed BECAUSE the previous quantum could not
    # express them. One envelope hop is 5 ms; 1, 7 and 40 samples are all inside
    # it at every rate used here.
    for d in (1, 7, 40, 100, 333, 1000):
        probe(f"delayed_{d}", shift(ref, d), d)
    ph = destroy_phase(ref, sr, rng)
    probe("phase_destroyed", ph, 0)
    for d in (7, 100, 1000):
        probe(f"phase_destroyed_delay_{d}", shift(ph, d), d)
    probe("band_limited_4k", band_limit(ref, sr, 4000.0), 0)
    probe("noise_10dB", add_noise(ref, 10.0, rng), 0)
    probe("different_speaker", other[:ref.size] if other.size >= ref.size
          else np.concatenate([other, np.zeros(ref.size - other.size)]))

    # D3. The residual is judged by WHAT IT COSTS the sole ranking metric, as a
    # fraction of the mildest declared damage rung - not by whether it is small
    # in the abstract.
    r2 = np.random.default_rng(SEED + 99)
    mild = num(call(lambda aa, bb, ss: G4.mcd(aa, bb, ss), ref,
                    add_noise(ref, SNR_LADDER_DB[0], r2), sr))
    costs = {}
    for tag, rec in list(P.items()):
        d = rec.get("expected_delay_samples")
        rep = rec.get("envelope_delay_samples")
        if d is None or rep is None:
            continue
        est = shift(ref, d) if d > 0 else ref
        m = num(call(lambda aa, bb, ss: G4.mcd(aa, bb, ss, delay_samples=rep),
                     ref, est, sr))
        costs[tag] = {"mcd_after_correction": m,
                      "fraction_of_mildest_rung":
                          (m / mild) if (m is not None and mild) else None}
    out["residual_cost_mcd"] = {
        "mildest_rung": mild,
        "max_fraction_allowed": ALIGN_RESIDUAL_MAX_FRACTION,
        "per_probe": costs,
    }
    clean = {k: c for k, c in costs.items() if not k.startswith("phase_destroyed")}
    inco = {k: c for k, c in costs.items() if k.startswith("phase_destroyed")}

    def worst(d):
        v = [c["fraction_of_mildest_rung"] for c in d.values()
             if c["fraction_of_mildest_rung"] is not None]
        return max(v) if v else None

    worst_clean, worst_inco = worst(clean), worst(inco)
    worst_frac = worst(costs)
    out["residual_cost_mcd"].update({
        "worst_fraction": worst_frac,
        "worst_fraction_clean": worst_clean,
        "worst_fraction_phase_incoherent": worst_inco,
        "clean_budget": ALIGN_CLEAN_MAX_FRACTION,
    })
    # GATE: clean-signal alignment must be essentially exact.
    cost_ok = (worst_clean is not None
               and worst_clean <= ALIGN_CLEAN_MAX_FRACTION)
    # MEASUREMENT, not a gate: the instrument floor on realistic output.
    # B2. RENAMED so it cannot be mistaken for the authoritative floors. This is
    # the SINGLE-DRAW alignment-level diagnostic that F2 WITHDREW as a rule. The
    # live floors are report["INSTRUMENT_FLOORS"] - per state, 16 draws, absolute.
    out["WITHDRAWN_single_draw_alignment_residual"] = {
        "fraction_of_mildest_mcd_rung": worst_inco,
        "mildest_rung_mcd": mild,
        "absolute_mcd": (worst_inco * mild) if (worst_inco and mild) else None,
        "measured_on": "phase-incoherent reconstructions at the REFERENCE-COMMON "
                       "ranking rate",
        "meaning": "the smallest mcd difference this apparatus can attribute to a "
                   "DECODER rather than to its own alignment residual. A measured "
                   "difference below this is NOT attributable to the decoder.",
        "status": "WITHDRAWN as a rule (F2). One phase draw; re-running the "
                  "identical construction gave 38.62 / 56.93 / 85.80 on the same "
                  "file and state. Retained ONLY as the alignment-gate "
                  "diagnostic. The live floors are INSTRUMENT_FLOORS.",
    }

    ph_keys = [k for k in P if k.startswith("phase_destroyed")]
    rec_ok = all(P[k].get("delay_recovered") for k in ph_keys
                 if P[k].get("expected_delay_samples") is not None)
    adm_ok = all(P[k]["state"] == "MEASURED" for k in ph_keys)
    old_would_fail = [k for k in ph_keys
                      if (P[k]["OLD_raw_waveform_r"] or 0) < 0.50]
    all_recovered = all(r.get("delay_recovered") for k, r in P.items()
                        if r.get("expected_delay_samples") is not None
                        and not k.startswith("phase_destroyed"))
    out["verdict"] = {
        "recovers_every_CLEAN_delay": bool(all_recovered),
        "admits_phase_destroyed_signals": bool(adm_ok),
        "clean_residual_within_budget": bool(cost_ok),
        "worst_clean_residual_fraction": worst_clean,
        "WITHDRAWN_single_draw_fraction": worst_inco,
        "INSTRUMENT_FLOOR_fraction_of_rung": worst_inco,
        "instrument_floor_is_a_measurement_not_a_gate": True,
        "old_method_would_have_rejected": old_would_fail,
        "different_speaker_rejected":
            P["different_speaker"]["state"] != "MEASURED",
        "verdict": ("FIT FOR PURPOSE"
                    if (adm_ok and all_recovered and cost_ok)
                    else "NOT FIT"),
        "why": "A tier-B gate must admit a spectrally faithful, "
               "phase-incoherent reconstruction. §5.1 states neural codecs do "
               "not preserve phase; a gate built on phase coherence has "
               "missingness correlated with the estimand.",
    }
    return out


# ---------------------------------------------------------------- main

def main():
    pairs, calib_idx, doc = calibration_material()
    base = pairs[0]
    sr = base["sr"]

    report = {
        "generated_by": "fuzz_gate4_lib.py",
        "seed": SEED,
        "calibration": {
            "source": SRC, "indices": calib_idx,
            "states": [p["state"] for p in pairs],
            "reference_files": {p["state"]: p["ref_path"] for p in pairs},
            "unrelated_files": {p["state"]: p["other_path"] for p in pairs},
            "held_out": "⭐ M7: these indices lie in [2.0,3.0)s on NEUTRAL, which "
                        "the Set S predicate [3.0,10.0]s excludes BY "
                        "CONSTRUCTION. No floor licensing a ranking is derived "
                        "from a recording the ranking is computed on.",
            "disjoint_from_set_S": doc["calibration"]["disjoint_from_set_S"],
            "disjoint_from_set_L": doc["calibration"]["disjoint_from_set_L"],
        },
        "resampler": G4.RESAMPLE,
        "gates_for_can_rank": [
            "G1 identity: identical input returns the declared identity value",
            "G2 monotonic: strictly ordered across the graded damage ladder",
            "G3 shift: a ONE-SAMPLE shift moves it LESS than the mildest damage",
            "G4 length: a truncated estimate is NOT scored as identity - a length "
            "failure must be a FAILURE STATE (B5)",
            "G5 zero: digital silence does NOT score at or better than the "
            "heaviest damage (amendment 6)",
        ],
        "recorded_declared_properties": [
            "gain response (M5) - a gain-sensitive metric ranks only in its "
            "gain-matched variant",
            "band-limit response (M3)",
            "unrelated-signal distance - DESCRIPTIVE, never an admissibility "
            "condition (the WITHDRAWN condition 4)",
            "rate-chain floor (B4)",
        ],
        "withdrawn_conditions": {
            "unrelated_exceeds_damage": {
                "status": "WITHDRAWN 2026-09-12, before any Gate 4 quality number",
                "why": "added AFTER seeing the first run - a post-hoc criterion "
                       "this methodology forbids - and it tested the wrong "
                       "property: a codec emits a DEGRADED version of the SAME "
                       "speech, never a DIFFERENT SPEAKER.",
            }
        },
        "metrics": {}, "attacks_run": 0, "probes_consumed": 0,
    }

    METRICS = {
        "mcd":            lambda a, b, s: G4.mcd(a, b, s),
        "lsd":            lambda a, b, s: G4.lsd(a, b, s),
        "lsd_gainmatched": lambda a, b, s: G4.lsd(a, b, s, gain_matched=True),
        "mrstft_mag":     lambda a, b, s: G4.mrstft_mag(a, b, s),
        "mrstft_gainmatched": lambda a, b, s: G4.mrstft_mag(a, b, s, gain_matched=True),
        "ltas_dist":      lambda a, b, s: G4.ltas_dist(a, b, s),
        "ltas_gainmatched": lambda a, b, s: G4.ltas_dist(a, b, s, gain_matched=True),
        "si_sdr":         lambda a, b, s: G4.si_sdr(a, b),
        "max_abs_err":    lambda a, b, s: G4.max_abs_err(a, b),
    }

    for name, fn in METRICS.items():
        rng = rng_for(name)
        x, other = base["ref"], base["other"]
        row = {"probes": {}, "by_state": {}, "rank_sr": sr}
        P = row["probes"]

        P["identical"] = call(fn, x, x, sr)
        for k in SHIFTS:
            P[f"shift_{k}"] = call(fn, x, shift(x, k), sr)
        for g in (0.5, 2.0):
            P[f"gain_x{g}"] = call(fn, x, x * g, sr)
        for snr in SNR_LADDER_DB:
            P[f"noise_{int(snr)}dB"] = call(fn, x, add_noise(x, snr, rng), sr)
        P["all_zero"] = call(fn, x, np.zeros_like(x), sr)
        P["nan_injected"] = call(fn, x, np.where(np.arange(x.size) == 100, np.nan, x), sr)
        P["inf_injected"] = call(fn, x, np.where(np.arange(x.size) == 100, np.inf, x), sr)
        P["truncated_256"] = call(fn, x, x[:-256], sr)
        P["truncated_1hop"] = call(fn, x, x[:-int(0.005 * sr)], sr)
        P["single_sample"] = call(fn, x, x[:1], sr)
        P["different_speaker"] = call(fn, x, other[:x.size] if other.size >= x.size
                                      else np.concatenate([other, np.zeros(x.size - other.size)]), sr)
        P["band_limited_8k"] = call(fn, x, band_limit(x, sr, 8000.0), sr)
        P["band_limited_4k"] = call(fn, x, band_limit(x, sr, 4000.0), sr)
        P["phase_destroyed"] = call(fn, x, destroy_phase(x, sr, rng), sr)
        # D2. UNKNOWN NEVER BECOMES 0.0 (R1). The previous lambda ended in
        # `or 0.0`, which mapped an UNKNOWN floor - and a legitimate 0.0 - onto
        # the same value inside the repaired instrument.
        def _floor_metric(aa, bb, ss):
            return num(call(fn, aa, bb, ss))
        row["rate_chain_floor_24k_out"] = G4.rate_chain_floor(
            x, sr, 24000, 24000, _floor_metric)
        # D9. THE FULL GATE BATTERY, PER STATE. Previously only `pairs[0]`
        # (Neutral) drove every gate while the per-state probes fed nothing -
        # 243 attacks run against 198 consumed. The recorded numbers already
        # showed `mcd`'s scale is state-dependent by ~2x at 20 dB SNR (Whisper
        # 325.6, Neutral 652.8, Shouting 627.6) and no gate consumed it.
        # F5. ALL pairs, including pairs[0]. `by_state` previously started at
        # pairs[1:], so NEUTRAL - the state driving every main probe - was never
        # itself state-gated, and "all six states" was in fact five.
        for p in pairs:
            r2 = rng_for(name + p["state"])
            xs = p["ref"]
            sp = {}
            sp["identical"] = call(fn, xs, xs, p["sr"])
            sp["shift_1"] = call(fn, xs, shift(xs, 1), p["sr"])
            for snr in SNR_LADDER_DB:
                sp[f"noise_{int(snr)}dB"] = call(fn, xs, add_noise(xs, snr, r2), p["sr"])
            sp["all_zero"] = call(fn, xs, np.zeros_like(xs), p["sr"])
            sp["truncated_256"] = call(fn, xs, xs[:-256], p["sr"])
            sp["gain_x2.0"] = call(fn, xs, xs * 2.0, p["sr"])
            oth = p["other"]
            oth = (oth[:xs.size] if oth.size >= xs.size
                   else np.concatenate([oth, np.zeros(xs.size - oth.size)]))
            sp["different_speaker"] = call(fn, xs, oth, p["sr"])
            for c in BAND_LIMITS_HZ:
                sp[f"band_{int(c)}"] = call(fn, xs, band_limit(xs, p["sr"], c), p["sr"])
            sp["verdict"] = state_gates(sp, SNR_LADDER_DB)
            row["by_state"][p["state"]] = sp
            report["attacks_run"] += len(sp) - 1
        report["attacks_run"] += len(P) + 1

        # ---------------- verdict: EVERY probe consumed
        ident = num(P["identical"])
        s1 = num(P["shift_1"])
        ladder = [num(P[f"noise_{int(s)}dB"]) for s in SNR_LADDER_DB]
        v, consumed = {}, 0

        # G1 - a metric whose perfect score is unbounded (si_sdr -> +inf) has a
        # WELL DEFINED identity; it simply is not a finite number. Rejecting it
        # as "no defined identity value" was wrong (m3).
        st_id = P["identical"].get("state")
        v["G1_identity"] = {
            "value": ident, "state": st_id,
            "pass": bool((ident is not None and abs(ident) < 1e-9)
                         or st_id == "DEGENERATE"),
            "note": ("identity is unbounded (exact copy) - well defined, not "
                     "finite" if st_id == "DEGENERATE" else None)}
        consumed += 1

        if all(l is not None for l in ladder):
            inc = all(ladder[i + 1] > ladder[i] for i in range(len(ladder) - 1))
            dec = all(ladder[i + 1] < ladder[i] for i in range(len(ladder) - 1))
            v["G2_monotonic"] = {"ladder": ladder, "pass": bool(inc or dec),
                                 "direction": "increases" if inc else
                                 ("decreases" if dec else "neither")}
        else:
            v["G2_monotonic"] = {"ladder": ladder, "pass": False,
                                 "direction": "UNKNOWN - ladder incomplete"}
        consumed += len(ladder)

        # G3 - DIRECTION AWARE. For a metric where LOWER means WORSE (si_sdr),
        # "distance from identity" is the wrong comparison and identity may be
        # unbounded. Compare the one-sample shift against the MILDEST DAMAGE on
        # the metric's own scale, using the direction the ladder established.
        d = v["G2_monotonic"]["direction"]
        mild = ladder[0]
        if None not in (s1, mild) and d in ("increases", "decreases"):
            worse = (s1 > mild) if d == "increases" else (s1 < mild)
            v["G3_shift"] = {
                "shift_1": s1, "mildest_damage": mild, "direction": d,
                "shift1_delta": (abs(s1 - ident) if ident is not None else None),
                "mildest_damage_delta": (abs(mild - ident) if ident is not None
                                         else None),
                "pass": bool(not worse),
                "note": "a ONE-SAMPLE shift must look LESS damaging than the "
                        "mildest genuine damage on this metric's own scale"}
        else:
            v["G3_shift"] = {"shift_1": s1, "mildest_damage": mild, "pass": False,
                             "reason": "ladder direction undetermined or shift "
                                       "not a number"}
        consumed += 1

        # ⭐ G4 - B5. A truncation must NOT come back as identity.
        tr = [("truncated_256", P["truncated_256"]), ("truncated_1hop", P["truncated_1hop"])]
        det = []
        for tag, rec in tr:
            val, st = num(rec), rec.get("state")
            detected = (st in ("LENGTH FAILURE", "UNKNOWN", "RAISED")) or \
                       (val is not None and ident is not None and abs(val - ident) > 1e-9)
            det.append(detected)
        v["G4_length"] = {
            "truncated_256": {"value": num(P["truncated_256"]),
                              "state": P["truncated_256"].get("state")},
            "truncated_1hop": {"value": num(P["truncated_1hop"]),
                               "state": P["truncated_1hop"].get("state")},
            "pass": all(det),
            "why": "§6 requires the vocos_mel24 / griffinlim b = -256 signature to "
                   "be DETECTED as a length failure, never absorbed into a "
                   "quality score.",
        }
        consumed += 2

        # ⭐ G5 - amendment 6. Silence must not score best.
        az, st_az = num(P["all_zero"]), P["all_zero"].get("state")
        worst = ladder[-1] if ladder and ladder[-1] is not None else None
        if st_az in ("DEGENERATE", "UNKNOWN", "RAISED", "LENGTH FAILURE"):
            ok_zero = True
        elif None in (az, worst, ident):
            ok_zero = False
        else:
            ok_zero = (abs(az - ident) > abs(worst - ident))
        v["G5_zero"] = {
            "value": az, "state": st_az, "worst_damage": worst,
            "pass": bool(ok_zero),
            "domain_note": "§8's validity gate rejects an output whose peak is "
                           "0, so digital silence never reaches a metric in the "
                           "study. G5 is nonetheless a GATE and not a waiver: a "
                           "metric whose ordering inverts at the quiet extreme "
                           "is not trusted to order arms near it."}
        consumed += 1

        # recorded declared properties - every remaining probe feeds one
        # ⭐ Gain sensitivity is judged RELATIVE TO THE METRIC'S OWN SCALE.
        # An absolute 1e-9 threshold is meaningless across metrics whose values
        # differ by three orders of magnitude: it flagged `mcd` as gain-sensitive
        # on a response of 5.5e-07, which is float noise, while `mcd` drops c0
        # precisely to BE gain-invariant. The reference scale is the mildest
        # genuine damage; anything under 1% of that is not sensitivity.
        GAIN_REL_TOL = 0.01
        gain = {k: num(P[k]) for k in ("gain_x0.5", "gain_x2.0")}
        scale = (abs(ladder[0] - ident)
                 if (ladder and ladder[0] is not None and ident is not None) else None)
        if scale and scale > 0:
            gain_moves = any(g is not None and abs(g - ident) > GAIN_REL_TOL * scale
                             for g in gain.values())
        else:
            gain_moves = any(g is not None and ident is not None
                             and abs(g - ident) > 1e-9 for g in gain.values())
        v["P_gain"] = {"values": gain, "gain_sensitive": bool(gain_moves),
                       "reference_scale": scale, "relative_tolerance": GAIN_REL_TOL,
                       "consequence": ("ranks only in its gain-matched variant"
                                       if gain_moves else "gain-invariant")}
        consumed += 2
        v["P_bandlimit"] = {"8k": num(P["band_limited_8k"]),
                            "4k": num(P["band_limited_4k"])}
        consumed += 2
        v["P_phase"] = {"value": num(P["phase_destroyed"])}
        consumed += 1
        v["P_unrelated_DESCRIPTIVE"] = {
            "different_speaker": num(P["different_speaker"]),
            "note": "DESCRIPTIVE ONLY - the condition built on this was WITHDRAWN"}
        consumed += 1
        v["P_nonfinite"] = {"nan": P["nan_injected"].get("state"),
                            "inf": P["inf_injected"].get("state"),
                            "pass": P["nan_injected"].get("state") != "MEASURED"
                            and P["inf_injected"].get("state") != "MEASURED"}
        consumed += 2
        v["P_degenerate_length"] = {"single_sample": P["single_sample"].get("state")}
        consumed += 1
        v["P_shift_curve"] = {f"shift_{k}": num(P[f"shift_{k}"]) for k in SHIFTS[1:]}
        consumed += len(SHIFTS) - 1
        v["P_rate_chain_floor"] = row["rate_chain_floor_24k_out"]["floor"]
        consumed += 1

        v["probes_total"] = len(P) + 1
        v["probes_consumed"] = consumed
        v["all_probes_consumed"] = consumed >= len(P) + 1

        # D9 - states are a GATE, not decoration.
        bad_states = [st for st, sp in row["by_state"].items()
                      if not sp["verdict"]["all_pass"]]
        v["P_states"] = {
            "evaluated": list(row["by_state"].keys()),
            "failing": bad_states,
            "pass": not bad_states,
            "why": "a metric that orders damage correctly on Neutral and fails "
                   "on Whisper cannot rank arms on a corpus containing both",
        }
        consumed += sum(len(sp) - 1 for sp in row["by_state"].values())

        forced = G4.REGISTRY.get(name.split("_gainmatched")[0], {}).get("can_rank")
        gates = ["G1_identity", "G2_monotonic", "G3_shift", "G4_length",
                 "G5_zero", "P_states"]
        failed = [g for g in gates if not v[g].get("pass")]
        if forced is False:
            v["verdict"] = "DETECTOR"
            v["reason"] = G4.REGISTRY[name.split("_gainmatched")[0]].get("why", "")
        elif failed:
            v["verdict"] = "DETECTOR"
            v["reason"] = "failed " + ", ".join(failed)
        elif gain_moves and "gainmatched" not in name:
            v["verdict"] = "DETECTOR"
            v["reason"] = ("gain-sensitive: this raw variant cannot separate a "
                           "level error from a spectral one; the gain-matched "
                           "variant carries the ranking (M5)")
        else:
            v["verdict"] = "SEVERITY SCALE"
            v["reason"] = "passed G1-G5" + ("" if gain_moves else " and gain-invariant")

        row["verdict"] = v
        report["metrics"][name] = row
        report["probes_consumed"] += consumed

    report["alignment_gate"] = fuzz_alignment(base["ref"], sr, base["other"],
                                              rng_for("alignment"))
    report["attacks_run"] += len(report["alignment_gate"]["probes"])

    # ---------------------------------------------------------------- F2
    # THE INSTRUMENT FLOOR AS A DISTRIBUTION: N draws x every state x every
    # metric that is still ranking-capable, each using THAT metric's own scale.
    rank_now = [k for k, r in report["metrics"].items()
                if r["verdict"]["verdict"] == "SEVERITY SCALE"]
    floors = {}
    for mname in rank_now:
        mfn = METRICS[mname]
        per_state = {}
        for pr in pairs:
            ss, xs = pr["sr"], pr["ref"]
            r0 = rng_for("floor|" + mname + "|" + pr["state"])
            mild = num(call(mfn, xs, add_noise(xs, SNR_LADDER_DB[0], r0), ss))
            draws = []
            for k in range(N_FLOOR_DRAWS):
                rk = np.random.default_rng(SEED + zlib.crc32(
                    ("floor|%s|%s|%d" % (mname, pr["state"], k)).encode()))
                ph = destroy_phase(xs, ss, rk)
                d = FLOOR_DELAYS[k % len(FLOOR_DELAYS)]
                est = shift(ph, d)
                al = G4.alignment(xs, est, ss)
                rep = al.get("delay_samples")
                if rep is None:
                    continue
                # Charge the metric for the ALIGNMENT RESIDUAL ONLY: the
                # estimate is a CLEAN shift of the reference, corrected by
                # whatever delay the aligner reported for the phase-incoherent
                # signal. Any remaining distance is the apparatus's own error.
                clean = shift(xs, d)
                v = num(call(lambda aa, bb, sss: (
                    G4.mcd(aa, bb, sss, delay_samples=rep) if mname == "mcd"
                    else G4.ltas_dist(aa, bb, sss, gain_matched=True,
                                      delay_samples=rep)), xs, clean, ss))
                if v is None or mild is None:
                    continue
                draws.append({"draw": k, "delay": d, "reported": rep,
                              "residual": int(d - rep), "value": v,
                              "fraction_of_rung": v / mild})
            fr = sorted(x["fraction_of_rung"] for x in draws)
            q = (float(np.quantile(fr, FLOOR_QUANTILE)) if fr else None)
            per_state[pr["state"]] = {
                "mildest_rung": mild, "n_draws": len(draws),
                "fractions_min": (fr[0] if fr else None),
                "fractions_max": (fr[-1] if fr else None),
                "quantile": FLOOR_QUANTILE,
                "floor_fraction_of_rung": q,
                "floor_absolute": (q * mild) if (q is not None and mild) else None,
                "draws": draws,
            }
            report["attacks_run"] += len(draws)
        qs = [v["floor_fraction_of_rung"] for v in per_state.values()
              if v["floor_fraction_of_rung"] is not None]
        floors[mname] = {
            "per_state": per_state,
            "worst_state_fraction": (max(qs) if qs else None),
            "state_aware": True,
            "construction": ("N=%d deterministic phase draws x %d states, "
                             "delays %s, production alignment path, held-out "
                             "calibration only, no decoder; floor = the %.2f "
                             "quantile of the residual cost distribution IN THAT "
                             "STATE" % (N_FLOOR_DRAWS, len(pairs), FLOOR_DELAYS,
                                        FLOOR_QUANTILE)),
        }
    report["INSTRUMENT_FLOORS"] = floors
    report["G6_ungated_band_2000"] = {
        m: {st: sp.get("band_2000", {}).get("value")
            for st, sp in r["by_state"].items()}
        for m, r in report["metrics"].items()}
    report["G6_gated_band_limits_hz"] = list(GATE_BAND_LIMITS_HZ)
    report["G6_reported_band_limits_hz"] = list(BAND_LIMITS_HZ)

    # ⭐ B6: evidence prose generated FROM THE PROBES, never typed by hand.
    ev = []
    for name, row in report["metrics"].items():
        v = row["verdict"]
        g3 = v["G3_shift"]
        # D13. Key on whether the GATE RAN, not on whether one optional field is
        # populated. The previous branch reported "G3 not computable" for si_sdr
        # while the artifact recorded G3 computed and FAILED (17.53 vs 39.98) -
        # because `shift1_delta` is undefined when identity is unbounded, though
        # the gate itself evaluated fine on the metric's own scale.
        if "reason" in g3:
            ev.append(f"{name}: G3 NOT EVALUATED - {g3['reason']}")
        else:
            ev.append(
                f"{name}: G3 {'PASS' if g3.get('pass') else 'FAIL'} - one-sample "
                f"shift reads {g3.get('shift_1'):.4g}, mildest damage reads "
                f"{g3.get('mildest_damage'):.4g}, and the ladder "
                f"{g3.get('direction')} with damage")
            if g3.get("shift1_delta") is not None:
                ev.append(
                    f"{name}: shift1_delta {g3['shift1_delta']:.4g} vs "
                    f"mildest_damage_delta {g3['mildest_damage_delta']:.4g} = "
                    f"{g3['shift1_delta'] / max(g3['mildest_damage_delta'], 1e-12):.3g}x")
        ev.append(f"{name}: VERDICT {v['verdict']} - {v['reason']}")
    report["evidence_lines"] = ev

    with open(os.path.join(HERE, "fuzz_gate4_lib.json"), "w") as f:
        json.dump(report, f, indent=1, default=str)

    print(f"calibration: indices {calib_idx} (HELD OUT), states "
          f"{[p['state'] for p in pairs]}")
    print(f"RANKING RATE (REFERENCE-COMMON): {sr} Hz   "
          f"[source material {pairs[0]['source_sr']} Hz -> resampled via "
          f"gate4_lib.RESAMPLE]")
    print(f"attacks run: {report['attacks_run']}   "
          f"probes consumed: {report['probes_consumed']}\n")
    print(f"{'metric':<21} {'G1':>4} {'G2':>4} {'G3':>4} {'G4':>4} {'G5':>4} "
          f"{'G6':>4} {'states':>7} {'gain':>6}  verdict")
    for name, row in report["metrics"].items():
        v = row["verdict"]
        def m(k):
            return "ok" if v[k].get("pass") else "FAIL"
        g6 = all(sp["verdict"].get("G6_spectral_support")
                 for sp in row["by_state"].values()) if row["by_state"] else False
        print(f"{name:<21} {m('G1_identity'):>4} {m('G2_monotonic'):>4} "
              f"{m('G3_shift'):>4} {m('G4_length'):>4} {m('G5_zero'):>4} "
              f"{('ok' if g6 else 'FAIL'):>4} {m('P_states'):>7} "
              f"{('sens' if v['P_gain']['gain_sensitive'] else 'inv'):>6}  "
              f"{v['verdict']}")
        if v["verdict"] == "DETECTOR":
            print(f"{'':>21} -> {v['reason']}")
    a = report["alignment_gate"]["verdict"]
    print(f"\nALIGNMENT GATE: {a['verdict']}")
    print(f"   recovers every CLEAN delay (tol {ALIGN_TOL_SAMPLES} samples) : "
          f"{a['recovers_every_CLEAN_delay']}")
    print(f"   admits phase-destroyed signals         : {a['admits_phase_destroyed_signals']}")
    wc = a.get('worst_clean_residual_fraction')
    print(f"   clean residual cost to mcd             : "
          f"{(f'{100*wc:.2f}%' if wc is not None else 'n/a')} of the mildest rung "
          f"(GATE, budget {100*ALIGN_CLEAN_MAX_FRACTION:.0f}%)")
    wi = a.get('INSTRUMENT_FLOOR_fraction_of_rung')
    print(f"   single-draw residual (WITHDRAWN as a rule): "
          f"{(f'{100*wi:.2f}%' if wi is not None else 'n/a')} - diagnostic only; "
          f"the live floors are per-state in INSTRUMENT_FLOORS")
    print(f"   OLD raw-waveform method would reject   : {a['old_method_would_have_rejected']}")
    print(f"   different speaker rejected             : {a['different_speaker_rejected']}")
    print("\nwrote fuzz_gate4_lib.json")
    return 0


if __name__ == "__main__":
    sys.exit(main())
